catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {

    if (isLoading) {
        return;
    }

    var field = 'affected_service_offering';
    var choice = 'outage_shield_choice';

    // Clear previous advisory messages.
    g_form.hideFieldMsg(field, true);
    g_form.hideFieldMsg(choice, true);

    // Reset subscription choice whenever service changes.
    g_form.setValue(choice, 'continue');
    g_form.setDisplay(choice, false);

    // No advisory needed for an unspecified service.
    if (!newValue || newValue === 'other') {
        return;
    }

    // Only recognise our approved employee-facing choices.
    if (newValue !== 'github' && newValue !== 'website') {
        return;
    }

    var selectedService = newValue;

    // Request current advisory from Outage Shield.
    var ga = new GlideAjax(
        'x_1951923_outage_0.OutageShieldAdvisoryAjax'
    );

    ga.addParam('sysparm_name', 'getAdvisory');

    ga.addParam(
        'sysparm_service_key',
        selectedService
    );

    ga.getXMLAnswer(function(answer) {

        // Ignore responses for a service no longer selected.
        if (g_form.getValue(field) !== selectedService) {
            return;
        }

        var data;

        try {
            data = JSON.parse(answer || '{}');
        } catch (e) {
            data = {
                error: true,
                alerts: []
            };
        }

        if (!data || data.error) {

            g_form.showFieldMsg(
                field,
                'Known-issue information is temporarily unavailable. ' +
                'You can still report your issue.',
                'info',
                false
            );

            return;
        }

        // No current known issue.
        if (!data.alerts || data.alerts.length === 0) {
            return;
        }

        var messages = [];

        for (var i = 0; i < data.alerts.length; i++) {

            var alert = data.alerts[i];

            var message =
                'A disruption reported by ' +
                alert.vendor +
                ' may affect this IT service. ' +
                'Internal impact is not yet confirmed.';

            if (alert.incidentNumber) {

                message +=
                    ' IT is tracking a potentially related issue ' +
                    'under ' + alert.incidentNumber + '.';
            }

            messages.push(message);
        }

        // Display non-blocking advisory.
        g_form.showFieldMsg(
            field,
            'POTENTIAL KNOWN ISSUE: ' +
            messages.join(' ') +
            ' You may not need to submit another Incident, ' +
            'but you can still continue if you need assistance.',
            'info',
            false
        );

        // Offer subscription instead of Incident submission.
        g_form.setDisplay(choice, true);

    });
}
